INSERT OR IGNORE INTO resources (title, url) VALUES
  ('Gerbicz, Meyrignac and Beckert: All solutions of a^6+b^6=c^6+d^6+e^6+f^6+g^6 for terms < 250000 (arXiv:1108.0462)', 'https://arxiv.org/abs/1108.0462'),
  ('Resta and Meyrignac: The smallest solutions to x^6+y^6=a^6+b^6+c^6+d^6+e^6 (Math. Comp. 2002)', 'https://doi.org/10.1090/S0025-5718-02-01445-X'),
  ('yoyo@home: Euler (6,2,5) found solutions', 'https://www.rechenkraft.net/yoyo/y_euler_solutions.php');

INSERT OR IGNORE INTO category_resources (category_id, resource_id)
SELECT '6-2-5', id FROM resources WHERE url IN ('https://arxiv.org/abs/1108.0462', 'https://doi.org/10.1090/S0025-5718-02-01445-X', 'https://www.rechenkraft.net/yoyo/y_euler_solutions.php');

CREATE TABLE import_6_2_5 (id TEXT PRIMARY KEY, contributor TEXT, left_terms TEXT, right_terms TEXT, discovered_at TEXT, identity_key TEXT);

-- 1. The 25 rows already on the site (submitted 2026-11-19).
UPDATE submissions
SET contributor_id = (SELECT c.id FROM import_6_2_5 i JOIN contributors c ON c.name = i.contributor
                      WHERE i.identity_key = submissions.identity_key),
    discovered_at = (SELECT i.discovered_at FROM import_6_2_5 i WHERE i.identity_key = submissions.identity_key)
WHERE category_id = '6-2-5'
  AND identity_key IN (SELECT identity_key FROM import_6_2_5)
  AND contributor_id = (SELECT id FROM contributors WHERE name = 'Resta and Meyrignac 2003');

UPDATE submission_resources
SET resource_id = (SELECT id FROM resources WHERE url = 'https://arxiv.org/abs/1108.0462')
WHERE role = 'tool'
  AND resource_id = (SELECT id FROM resources WHERE url = 'https://github.com/elijahkin/diophantine/blob/main/resta_meyrignac.pdf')
  AND submission_id IN (SELECT s.id FROM submissions s JOIN import_6_2_5 i
                        ON s.category_id = '6-2-5' AND s.identity_key = i.identity_key);

INSERT OR IGNORE INTO submission_resources (submission_id, resource_id, role)
SELECT s.id, r.id, 'source'
FROM submissions s
JOIN import_6_2_5 i ON s.category_id = '6-2-5' AND s.identity_key = i.identity_key
JOIN resources r ON r.url = 'https://doi.org/10.1090/S0025-5718-02-01445-X'
WHERE i.discovered_at < '2003-01-01';

-- 2. The new rows.
SELECT i.id, '6-2-5', c.id, i.left_terms, i.right_terms, NULL, i.discovered_at
FROM import_6_2_5 i
JOIN contributors c ON c.name = i.contributor
WHERE NOT EXISTS (
  SELECT 1 FROM submissions s WHERE s.category_id = '6-2-5' AND s.identity_key = i.identity_key
);

-- One tool link per row (the leaderboard joins a single tool).
INSERT OR IGNORE INTO submission_resources (submission_id, resource_id, role)
SELECT s.id, r.id, 'tool'
FROM submissions s
JOIN import_6_2_5 i ON s.category_id = '6-2-5' AND s.identity_key = i.identity_key
JOIN resources r ON r.url = 'https://arxiv.org/abs/1108.0462'
WHERE NOT EXISTS (SELECT 1 FROM submission_resources t WHERE t.submission_id = s.id AND t.role = 'tool');

-- yoyo@home documents the dates of the 352 rows dated from it.
INSERT OR IGNORE INTO submission_resources (submission_id, resource_id, role)
SELECT s.id, r.id, 'source'
FROM submissions s
JOIN import_6_2_5 i ON s.category_id = '6-2-5' AND s.identity_key = i.identity_key
JOIN resources r ON r.url = 'https://www.rechenkraft.net/yoyo/y_euler_solutions.php'
WHERE i.discovered_at >= '2003-01-01';

-- 3. The search is complete below 250000 (each workunit computed at least twice).
INSERT OR IGNORE INTO search_claims
  (id, category_id, contributor_id, lower_radius, upper_radius, search_type, comment, created_at)
SELECT 'boinc-625-radius-250000', '6-2-5', id, '0', '250000', 'exhaustive',
       'All 377 primitive solutions with every term below 250000; BOINC projects April 2010 - July 2011, each workunit computed at least twice.',
       '2011-08-02T00:00:00Z'
FROM contributors WHERE name = 'Robert Gerbicz, Jean-Charles Meyrignac and Uwe Beckert';

INSERT OR IGNORE INTO search_claim_resources (search_claim_id, resource_id)
SELECT 'boinc-625-radius-250000', id FROM resources WHERE url = 'https://arxiv.org/abs/1108.0462';

DROP TABLE import_6_2_5;
